        elif p in ("kurslar", "rezervasyon") and ctx and (("/" + p) in [h for h, _ in sektor_mod.site_links(ctx.get("sector") or "")] or await getattr(db, "programs" if p == "kurslar" else "resources").count_documents({}) > 0):
