  function yedekCard() {
    var ex = document.getElementById('spx-yd'), u = me(), on = /^\/admin\/governance\/?$/.test(location.pathname) && !document.body.classList.contains('spx-tech') && (!u.admin_role || u.admin_role === 'owner'), mn = document.querySelector('main');
